WITH valid AS (SELECT *, CAST(pressure AS INT) AS pressure_int FROM device_readings WHERE reading_ts > TIMESTAMP '2025-09-01 01:00:00' AND status_bits <= 9) SELECT id, device_code, reading_ts, temp_c, status_bits, firmware, pressure_int, LEAD(temp_c) OVER w_ordered AS next_temp_c, LAG(temp_c) OVER w_ordered AS prev_temp_c, LEAD(status_bits) OVER w_ordered AS next_status_bits, ROW_NUMBER() OVER w_ordered AS row_seq FROM valid WINDOW w_ordered AS (PARTITION BY device_code ORDER BY humidity, id);
